import random
import math

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Reputation tracking: for each other agent, count of cooperative and defective actions observed
        self.coop_counts = {}
        self.defect_counts = {}
        # Track history of my own interactions: list of (opponent_id, my_action, opp_action)
        self.my_history = []
        # Track rounds played count
        self.rounds_played = 0
        # Track recent opponent identities
        self.last_opponents = []

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True
        # Get history with this opponent
        history = [h for h in self.my_history if h[0] == opp]
        if len(history) >= 3:
            # If opponent defected in last interaction, retaliate
            last = history[-1]
            if last[2] == 'defect':
                return False
            # If opponent cooperated at least twice in a row, continue cooperating
            if len(history) >= 2 and history[-1][2] == 'cooperate' and history[-2][2] == 'cooperate':
                return True
            # Otherwise, defect if they've defected more than cooperated overall
            coop = sum(1 for h in history if h[2] == 'cooperate')
            defect = len(history) - coop
            return coop >= defect
        # If little history, use reputation
        coop = self.coop_counts.get(opp, 0)
        defect = self.defect_counts.get(opp, 0)
        total = coop + defect
        if total == 0:
            return True  # No info, cooperate
        # Cooperate if reputation is >= 50% cooperative
        return coop / total >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation counts for both parties
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + 1
            else:
                self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + 1
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_counts[recipient_id] = self.coop_counts.get(recipient_id, 0) + 1
            else:
                self.defect_counts[recipient_id] = self.defect_counts.get(recipient_id, 0) + 1
        # If this is my own interaction, record it
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id
            self.my_history.append((opp_id, my_action, opp_action))
            self.rounds_played += 1
            self.last_opponents.append(opp_id)
            # Keep history bounded to last 100 interactions
            if len(self.my_history) > 100:
                self.my_history.pop(0)

