class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = -1
        self.generation = 0
        self.round = 0
        # Reputation scores: id -> float, initialized 0
        self.reputation = {}
        # Own history: list of (opponent_id, my_action, opp_action, round)
        self.own_history = []
        # Memory of recent interactions (for tit-for-tat style)
        self.last_actions = {}  # opponent_id -> my last action
        # Cooperation statistics for each agent
        self.coop_count = {}
        self.defect_count = {}
        self.interaction_count = {}
        # Group trust: simple weighted average of observed cooperation rates
        self.overall_coop_rate = 0.5
        self.total_observations = 0

    def decide(self) -> bool:
        # Get opponent
        opp = self._ctx_opponent_id
        self.opponent_id = opp

        # If we have interacted before, use tit-for-tat with forgiveness
        if opp in self.last_actions:
            # If last time they cooperated (or we haven't seen them defect recently), cooperate
            # Simple strategy: cooperate if last action was cooperate
            if self.last_actions[opp] == "cooperate":
                return True
            else:
                # If they defected last time, defect unless reputation is very high
                # Allow forgiveness if their overall cooperation rate is high
                if self.get_coop_rate(opp) > 0.7:
                    return True
                else:
                    return False
        else:
            # First interaction: cooperate with probability based on overall trust
            # If overall cooperation rate in population is high, cooperate
            if self.overall_coop_rate > 0.5:
                return True
            else:
                # Otherwise, defect sometimes, but be somewhat trusting
                return random.random() < 0.5

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == "cooperate":
                self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
            else:
                self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1
            self.interaction_count[agent_id] = self.interaction_count.get(agent_id, 0) + 1
            # Update reputation: cooperate +1, defect -1, bounded
            self.reputation[agent_id] = self.reputation.get(agent_id, 0) + (1 if action == "cooperate" else -1)
            # Keep reputation in [-10, 10] to avoid extreme values
            self.reputation[agent_id] = max(-10, min(10, self.reputation[agent_id]))

        # Update overall cooperation rate (simple moving average)
        self.total_observations += 1
        # Use exponential moving average with alpha = 0.1
        alpha = 0.1
        current_coop = 1.0 if (donor_action == "cooperate" and recipient_action == "cooperate") else 0.0
        self.overall_coop_rate = (1 - alpha) * self.overall_coop_rate + alpha * current_coop

        # If this is self-observation, record own action
        if donor_id == self.agent_id:
            self.last_actions[recipient_id] = donor_action
        if recipient_id == self.agent_id:
            self.last_actions[donor_id] = recipient_action

    def get_coop_rate(self, agent_id):
        total = self.coop_count.get(agent_id, 0) + self.defect_count.get(agent_id, 0)
        if total == 0:
            return 0.5
        return self.coop_count[agent_id] / total

