class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {i: 0.5 for i in range(15)}
        self.trust = {i: 0.5 for i in range(15)}
        self.opponent_id = None
        self.round = 0
        self.observed_coop = {}
        self.observed_defect = {}
        self.self_coop = 0
        self.self_defect = 0

    def decide(self) -> bool:
        self.round += 1
        self.opponent_id = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        if self.opponent_id is None:
            return True

        # Base strategy: cooperate if opponent's reputation is decent
        rep = self.reputation.get(self.opponent_id, 0.5)
        trust = self.trust.get(self.opponent_id, 0.5)

        # Combine reputation and trust with a slight bias toward cooperation
        score = 0.6 * rep + 0.4 * trust
        # Add small noise to avoid deterministic patterns
        noise = random.uniform(-0.05, 0.05)
        return score + noise > 0.5

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation based on donor action
        if donor_action == 'cooperate':
            self.reputation[donor_id] = min(1.0, self.reputation.get(donor_id, 0.5) + 0.1)
        else:
            self.reputation[donor_id] = max(0.0, self.reputation.get(donor_id, 0.5) - 0.1)

        # Update reputation based on recipient action (they also chose)
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = min(1.0, self.reputation.get(recipient_id, 0.5) + 0.1)
        else:
            self.reputation[recipient_id] = max(0.0, self.reputation.get(recipient_id, 0.5) - 0.1)

        # Track trust for self interactions
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                other = recipient_id
                other_action = recipient_action
                my_action = donor_action
            else:
                other = donor_id
                other_action = donor_action
                my_action = recipient_action

            # Update trust based on both actions
            if my_action == 'cooperate' and other_action == 'cooperate':
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.2)
            elif my_action == 'cooperate' and other_action == 'defect':
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - 0.3)
            elif my_action == 'defect' and other_action == 'cooperate':
                self.trust[other] = min(1.0, self.trust.get(other, 0.5) + 0.1)
            else:
                self.trust[other] = max(0.0, self.trust.get(other, 0.5) - 0.1)

        # Track observation counts for more precise reputation updates later
        if donor_id not in self.observed_coop:
            self.observed_coop[donor_id] = 0
            self.observed_defect[donor_id] = 0
        if donor_action == 'cooperate':
            self.observed_coop[donor_id] += 1
        else:
            self.observed_defect[donor_id] += 1

        if recipient_id not in self.observed_coop:
            self.observed_coop[recipient_id] = 0
            self.observed_defect[recipient_id] = 0
        if recipient_action == 'cooperate':
            self.observed_coop[recipient_id] += 1
        else:
            self.observed_defect[recipient_id] += 1

