class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # reputation scores for each other agent, 0..1
        self.interaction_history = {}  # agent_id -> list of outcomes for direct interactions
        self.coop_counts = {}  # agent_id -> number of cooperative actions observed (direct or indirect)
        self.total_obs = {}    # agent_id -> total actions observed
        self.generation = 0
        self.round_num = 0
        self.last_opponent = None
        self.my_coop_count = 0
        self.my_total_rounds = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # fallback
        self.last_opponent = opponent
        # Start with a neutral reputation if unknown
        rep = self.reputation.get(opponent, 0.5)
        # More cooperative if opponent has good reputation
        # Threshold tuned to be forgiving but not exploitable
        if rep >= 0.55:
            return True
        elif rep <= 0.35:
            return False
        else:
            # In ambiguous zone, use a deterministic pattern based on my own history
            # If I've been cooperating a lot, occasionally defect to avoid being taken advantage of
            if self.my_total_rounds > 0:
                coop_rate = self.my_coop_count / self.my_total_rounds
                if coop_rate > 0.75:
                    # Defect every 5th time in this zone
                    return (self.round_num % 5) != 0
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation based on observed actions
        # For each agent involved, update their cooperation count
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue  # don't update self reputation from self-observation? Actually we can but careful
            # Update counts
            self.total_obs[agent_id] = self.total_obs.get(agent_id, 0) + 1
            if action == 'cooperate':
                self.coop_counts[agent_id] = self.coop_counts.get(agent_id, 0) + 1
            # Compute reputation as cooperation rate
            total = self.total_obs[agent_id]
            if total > 0:
                coop = self.coop_counts[agent_id]
                self.reputation[agent_id] = coop / total

        # Update own interaction history if I am involved
        if donor_id == self.agent_id:
            self.my_total_rounds += 1
            if donor_action == 'cooperate':
                self.my_coop_count += 1
        if recipient_id == self.agent_id:
            self.my_total_rounds += 1
            if recipient_action == 'cooperate':
                self.my_coop_count += 1

        # Track direct interactions separately for potentially better memory
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            self.interaction_history.setdefault(other, []).append((my_action, other_action))
        # Keep history bounded
        if len(self.interaction_history) > 100:
            # trim oldest entries
            for key in list(self.interaction_history.keys()):
                if len(self.interaction_history[key]) > 50:
                    self.interaction_history[key] = self.interaction_history[key][-50:]

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> estimated cooperation probability
        self.my_actions = []  # history of my actions
        self.opponent_actions = {}  # opponent_id -> list of actions against me
        self.round_num = 0
        self.generation = 0
        self.last_opponent = None
        self.coop_count = 0
        self.defect_count = 0
        self.total_rounds = 0
        self.trust_threshold = 0.5
        self.initial_trust = 0.5
        self.forgiveness = 0.1
        self.epsilon = 0.05  # exploration noise

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Update round/generation counters (framework doesn't tell us directly, approximate)
        self.total_rounds += 1
        if self.total_rounds % 30 == 1:
            self.generation += 1
            self.round_num = 1
        else:
            self.round_num += 1

        # Get reputation estimate for opponent
        if opponent not in self.reputation:
            self.reputation[opponent] = self.initial_trust

        rep = self.reputation[opponent]

        # Simple adaptive strategy with exploration
        if random.random() < self.epsilon:
            return random.random() < 0.5

        # If opponent has low reputation, defect; else cooperate
        if rep < self.trust_threshold:
            return False
        else:
            return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation based on observed actions
        # For donor: if they cooperate, increase reputation; if defect, decrease
        # For recipient: we can also infer something about their behavior but less directly

        # Update donor reputation
        if donor_id != self.agent_id:
            if donor_id not in self.reputation:
                self.reputation[donor_id] = self.initial_trust
            if donor_action == 'cooperate':
                self.reputation[donor_id] += self.forgiveness
            else:
                self.reputation[donor_id] -= self.forgiveness
            # Keep within [0,1]
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

        # Update recipient reputation (they chose an action too)
        if recipient_id != self.agent_id:
            if recipient_id not in self.reputation:
                self.reputation[recipient_id] = self.initial_trust
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] += self.forgiveness
            else:
                self.reputation[recipient_id] -= self.forgiveness
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

        # Record my own actions for potential self-assessment
        if donor_id == self.agent_id:
            self.my_actions.append(donor_action)
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1

        if recipient_id == self.agent_id:
            self.my_actions.append(recipient_action)
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1

        # Track opponent actions against me
        if donor_id == self.agent_id:
            opp = recipient_id
            action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            action = donor_action
        else:
            opp = None
            action = None
        if opp is not None:
            if opp not in self.opponent_actions:
                self.opponent_actions[opp] = []
            self.opponent_actions[opp].append(action)
            # Update reputation based on direct interaction
            if action == 'cooperate':
                if opp in self.reputation:
                    self.reputation[opp] += 0.1
                else:
                    self.reputation[opp] = self.initial_trust + 0.1
            else:
                if opp in self.reputation:
                    self.reputation[opp] -= 0.2
                else:
                    self.reputation[opp] = self.initial_trust - 0.2
            self.reputation[opp] = max(0.0, min(1.0, self.reputation[opp]))

