        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.total_interactions = {}
        self.own_actions = []
        self.opponent_actions = {}
        self.trust = {}
        self.generation = 0
        self.round = 0
        self.tit_for_tat = {}
        self.cooperate_bias = 0.5
        self.defection_threshold = 0.4
        self.memory = {}
        self.epsilon = 0.05
        self.generosity = 0.1
        self.last_opponent = None
        self.my_last_action = None
        self.opponent_last_action = None

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent
        if opponent not in self.reputation:
            # Unknown opponent: start with neutral and slight bias to cooperate
            return random.random() < 0.6

        # Tit-for-tat with forgiveness
        if opponent in self.tit_for_tat and self.opponent_last_action is not None:
            if self.opponent_last_action == 'defect':
                # Forgive with small probability
                if random.random() < self.generosity:
                    return True
                else:
                    return False
            else:
                return True

        # Reputation-based decision
        rep = self.reputation.get(opponent, 0.0)
        cooperations = self.cooperation_count.get(opponent, 0)
        defections = self.total_interactions.get(opponent, 0) - cooperations
        if self.total_interactions.get(opponent, 0) > 0:
            coop_rate = cooperations / self.total_interactions[opponent]
        else:
            coop_rate = 0.5

        # Trust based on observed behavior
        if coop_rate > 0.7:
            return True
        elif coop_rate < 0.3:
            return False
        else:
            # Mixed: use reputation and personal experience
            personal_bias = 0.0
            if opponent in self.trust:
                personal_bias = self.trust[opponent]
            score = 0.5 * rep + 0.3 * coop_rate + 0.2 * personal_bias
            return score >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global reputation for observed actions
        # Donor behavior
        if donor_id != self.agent_id and donor_id not in self.reputation:
            self.reputation[donor_id] = 0.0
        if donor_id != self.agent_id:
            delta = 0.1 if donor_action == 'cooperate' else -0.1
            self.reputation[donor_id] = max(-1.0, min(1.0, self.reputation.get(donor_id, 0.0) + delta))
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
            self.total_interactions[donor_id] = self.total_interactions.get(donor_id, 0) + 1

        # Recipient behavior
        if recipient_id != self.agent_id and recipient_id not in self.reputation:
            self.reputation[recipient_id] = 0.0
        if recipient_id != self.agent_id:
            delta = 0.1 if recipient_action == 'cooperate' else -0.1
            self.reputation[recipient_id] = max(-1.0, min(1.0, self.reputation.get(recipient_id, 0.0) + delta))
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + (1 if recipient_action == 'cooperate' else 0)
            self.total_interactions[recipient_id] = self.total_interactions.get(recipient_id, 0) + 1

        # If this is my own interaction, update personal trust and tit-for-tat
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            other = recipient_id if donor_id == self.agent_id else donor_id
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            my_action = donor_action if donor_id == self.agent_id else recipient_action

            # Store last actions for tit-for-tat
            self.opponent_last_action = other_action
            self.my_last_action = my_action

            # Update trust based on outcome
            if other not in self.trust:
                self.trust[other] = 0.0
            if my_action == 'cooperate' and other_action == 'cooperate':
                self.trust[other] += 0.15
            elif my_action == 'defect' and other_action == 'cooperate':
                self.trust[other] += 0.1
            elif my_action == 'cooperate' and other_action == 'defect':
                self.trust[other] -= 0.2
            else:  # both defect
                self.trust[other] -= 0.05
            self.trust[other] = max(-1.0, min(1.0, self.trust[other]))

            # Update tit-for-tat memory
            self.tit_for_tat[other] = other_action

        # Increment round counter (approximate; we don't know exactly when rounds change)
        self.round += 1
        if self.round % 30 == 0:
            self.generation += 1
            # Decay reputation over time to adapt
            for key in list(self.reputation.keys()):
                self.reputation[key] *= 0.95
            # Decay trust
            for key in list(self.trust.keys()):
                self.trust[key] *= 0.95
            # Increase generosity slightly over generations to promote cooperation
            self.generosity = min(0.3, self.generosity + 0.01)

