        self.epsilon = 0.04  # exploration noise

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # safe fallback

        # Get opponent's reputation (default 0.5 neutral)
        opp_rep = self.reputation.get(opponent, 0.5)
        # Get personal history with this opponent
        hist = self.personal_history.get(opponent, [])
        if len(hist) >= 5:
            recent = hist[-5:]
            coop_freq = recent.count('cooperate') / len(recent)
        else:
            coop_freq = 0.5  # unknown

        # Combine reputation and personal experience
        combined = 0.6 * opp_rep + 0.4 * coop_freq

        # Defect if opponent seems untrustworthy
        if combined < self.trust_threshold:
            # With small probability, forgive and cooperate
            if random.random() < self.forgiveness:
                return True
            return False
        else:
            # Cooperate, but with small exploration noise
            if random.random() < self.epsilon:
                return False
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update round counter
        self.round += 1
        if self.round % 30 == 1:
            self.generation += 1

        # Update reputation based on observed actions
        # Cooperate gives +1, defect gives -1, scaled to [0,1]
        delta = 0.1
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + delta
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - delta
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + delta
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - delta
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

        # Update personal history if we are involved
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            # Record opponent's action
            if recipient_id in self.personal_history:
                self.personal_history[recipient_id].append(recipient_action)
                if len(self.personal_history[recipient_id]) > self.memory_limit:
                    self.personal_history[recipient_id] = self.personal_history[recipient_id][-self.memory_limit:]
            else:
                self.personal_history[recipient_id] = [recipient_action]

        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.cooperation_count += 1
            else:
                self.defection_count += 1
            # Record donor's action
            if donor_id in self.personal_history:
                self.personal_history[donor_id].append(donor_action)
                if len(self.personal_history[donor_id]) > self.memory_limit:
                    self.personal_history[donor_id] = self.personal_history[donor_id][-self.memory_limit:]
            else:
