        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self._ctx_opponent_id = None
        self.trust_threshold = 0.55
        self.memory_limit = 30  # keep last 30 interactions per opponent
        self.forgiveness = 0.1
        self.epsilon = 0.05  # exploration noise (small increase)

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # safe fallback

