class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.coop_count = {}
        self.defect_count = {}
        self.interactions = {}
        self.base_trust = 0.0
        self.my_actions = []
        self.exploited_count = 0
        self.total_coop = 0
        self.total_actions = 0

    def _get_reputation(self, agent_id):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = 0.0
        return self.reputation[agent_id]

    def _update_reputation(self, agent_id, delta):
        self.reputation[agent_id] = self._get_reputation(agent_id) + delta
        self.reputation[agent_id] = max(-10.0, min(10.0, self.reputation[agent_id]))

    def _record_action(self, agent_id, action):
        if action == 'cooperate':
            self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
        else:
            self.defect_count[agent_id] = self.defect_count.get(agent_id, 0) + 1

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self._get_reputation(opponent)
        history = self.interactions.get(opponent, [])
        if history:
            recent = history[-5:]
            their_coop = sum(1 for _, their in recent if their == 'cooperate')
            their_rate = their_coop / len(recent)
            trust_score = 0.5 * rep + 0.5 * (their_rate * 4 - 2)
        else:
            trust_score = rep + 0.5

        threshold = self.base_trust - self.exploited_count * 0.12
        threshold = max(-1.0, min(1.0, threshold))

        cooperate = trust_score > threshold
        if random.random() < 0.05:
            cooperate = not cooperate
        return cooperate

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        is_self = (donor_id == self.agent_id) or (recipient_id == self.agent_id)
        if is_self:
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            other_action = recipient_action if donor_id == self.agent_id else donor_action
            other_id = recipient_id if donor_id == self.agent_id else donor_id
            if other_id not in self.interactions:
                self.interactions[other_id] = []
            self.interactions[other_id].append((my_action, other_action))
            if my_action == 'cooperate':
                self.total_coop += 1
            self.total_actions += 1
            if my_action == 'cooperate' and other_action == 'defect':
                self.exploited_count += 1
            return

        if donor_action == 'cooperate':
            self._update_reputation(donor_id, 0.1)
        else:
            self._update_reputation(donor_id, -0.3)

        if recipient_action == 'cooperate':
            self._update_reputation(recipient_id, 0.1)
        else:
            self._update_reputation(recipient_id, -0.3)

        self._record_action(donor_id, donor_action)
        self._record_action(recipient_id, recipient_action)

