class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.temperature = 0.3
        self.cooperation_history = {}  # agent_id -> list of actions (True/False)
        self.my_actions = []
        self.opponent_ids = []
        self.round = 0
        self.epsilon = 0.05
        self.trust = {}  # agent_id -> trust score 0..1
        self.own_coop_count = 0
        self.own_defect_count = 0
        self.observed_coop = {}  # agent_id -> count
        self.observed_defect = {}  # agent_id -> count
        self.current_opponent = None

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        self.current_opponent = opp
        # Initialize trust for new opponents
        if opp not in self.trust:
            self.trust[opp] = 0.5
        # Get opponent's history with me
        opp_history = self.cooperation_history.get(opp, [])
        my_history_against_opp = [a for i, a in enumerate(self.my_actions) if self.opponent_ids[i] == opp]
        # Simple strategy: cooperate if opponent has been mostly cooperative, defect if mostly defecting
        if opp_history:
            coop_rate = sum(opp_history) / len(opp_history)
            if coop_rate > 0.6:
                action = True
            elif coop_rate < 0.4:
                action = False
            else:
                # Tit-for-tat style: match opponent's last action
                action = opp_history[-1]
        else:
            # First encounter: cooperate with some probability based on trust
            action = random.random() < (0.5 + self.trust[opp] * 0.5)
        # Add a bit of noise to avoid being too predictable
        if random.random() < self.epsilon:
            action = not action
        # Record my action and opponent
        self.round += 1
        self.my_actions.append(action)
        self.opponent_ids.append(opp)
        if action:
            self.own_coop_count += 1
        else:
            self.own_defect_count += 1
        return action

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update cooperation history for both agents
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent not in self.cooperation_history:
                self.cooperation_history[agent] = []
            self.cooperation_history[agent].append(action == 'cooperate')
            if agent not in self.observed_coop:
                self.observed_coop[agent] = 0
                self.observed_defect[agent] = 0
            if action == 'cooperate':
                self.observed_coop[agent] += 1
            else:
                self.observed_defect[agent] += 1
        # Update trust based on observed actions
        # Trust increases when agent cooperates, decreases when defects
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent not in self.trust:
                self.trust[agent] = 0.5
            if action == 'cooperate':
                self.trust[agent] = min(1.0, self.trust[agent] + 0.1)
            else:
                self.trust[agent] = max(0.0, self.trust[agent] - 0.1)

