import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, store a score
        # Positive = cooperative, negative = defective
        self.reputation = {}
        # Track cooperation rate of self and others
        self.coop_count = {}
        self.total_count = {}
        # Track recent interactions with each agent for forgiveness
        self.recent_interactions = {}
        # Track own performance
        self.own_coop = 0
        self.own_total = 0
        # Memory of last few rounds for pattern detection
        self.history = []
        # Parameter for forgiveness
        self.forgiveness = 0.1
        # Initial trust
        self.initial_trust = 0.0

    def _get_reputation(self, agent_id: int) -> float:
        return self.reputation.get(agent_id, self.initial_trust)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        if agent_id == self.agent_id:
            return
        # Update coop count and total
        self.total_count[agent_id] = self.total_count.get(agent_id, 0) + 1
        if action == 'cooperate':
            self.coop_count[agent_id] = self.coop_count.get(agent_id, 0) + 1
        # Compute reputation as cooperation rate minus default
        total = self.total_count[agent_id]
        coop = self.coop_count.get(agent_id, 0)
        rate = coop / total if total > 0 else 0.0
        # Reputation is centered around 0.5 base
        self.reputation[agent_id] = rate - 0.5

    def _update_recent(self, other_id: int, my_action: str, other_action: str) -> None:
        if other_id not in self.recent_interactions:
            self.recent_interactions[other_id] = []
        self.recent_interactions[other_id].append((my_action, other_action))
        # Keep last 5 interactions
        if len(self.recent_interactions[other_id]) > 5:
            self.recent_interactions[other_id].pop(0)

    def _forgiveness_factor(self, other_id: int) -> float:
        """Compute forgiveness based on recent interactions and own history"""
        # If we have been cooperating a lot, be more forgiving
        if self.own_total > 0:
            own_rate = self.own_coop / self.own_total
        else:
            own_rate = 0.5
        base_forgiveness = self.forgiveness * (1 + own_rate)
        # If the other agent has cooperated recently, increase forgiveness
        recent = self.recent_interactions.get(other_id, [])
        if recent:
            last_actions = [a for _, a in recent[-3:]]
            if 'cooperate' in last_actions:
                base_forgiveness += 0.1
        return base_forgiveness

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # No opponent, cooperate by default
        rep = self._get_reputation(opponent)
        # Simple strategy: cooperate if reputation is not too negative
        # and we haven't been exploited too much recently
        if rep >= -0.2:
            # Check recent interactions for betrayal
            recent = self.recent_interactions.get(opponent, [])
            if recent:
                # Count how many times we cooperated and they defected
                betrayals = sum(1 for my, other in recent if my == 'cooperate' and other == 'defect')
                if betrayals >= 2:
                    # If betrayed twice in last 5, defect unless they've cooperated since
                    last_other = recent[-1][1]
                    if last_other != 'cooperate':
                        return False
            return True
        else:
            # Negative reputation, but allow redemption
            # Check if they have cooperated in the most recent interaction
            recent = self.recent_interactions.get(opponent, [])
            if recent and recent[-1][1] == 'cooperate':
                # Give a chance to redeem
                return True
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for both agents (if not self)
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)
        # If we are involved, update our own stats and recent interactions
        if donor_id == self.agent_id:
            self.own_total += 1
            if donor_action == 'cooperate':
                self.own_coop += 1
            # Update recent interaction with recipient
            self._update_recent(recipient_id, donor_action, recipient_action)
        elif recipient_id == self.agent_id:
            self.own_total += 1
            if recipient_action == 'cooperate':
                self.own_coop += 1
            # Update recent interaction with donor
            self._update_recent(donor_id, recipient_action, donor_action)
        else:
            # Third-party observation: no direct interaction, just update reputation
            pass
        # Keep history of own actions for pattern detection (optional)
        if donor_id == self.agent_id:
            self.history.append(('D', donor_action))
        if recipient_id == self.agent_id:
            self.history.append(('R', recipient_action))
        # Keep history bounded
        if len(self.history) > 100:
            self.history.pop(0)

