class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation history per opponent: {opponent_id: [True/False, ...]}
        self.history = {}
        # Track reputation: {agent_id: [cooperate_count, defect_count, observed_count]}
        self.reputation = {}
        # Track own actions and outcomes
        self.my_actions = []
        self.my_last_opponent = None
        # Parameters for strategy
        self.generosity = 0.1  # Probability to cooperate when opponent is bad
        self.forgiveness = 0.3  # Probability to forgive a past defection
        self.trust_threshold = 0.3  # Minimum cooperation rate to trust
        self.defect_bias = 0.2  # Extra chance to defect if opponent defects often
        # Keep track of rounds and generations (approx via rounds count)
        self.round_count = 0

    def decide(self) -> bool:
        # Get opponent ID from context
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True  # No opponent info, cooperate by default
        self.my_last_opponent = opponent
        self.round_count += 1

        # Retrieve opponent's history with us
        opp_history = self.history.get(opponent, [])
        if not opp_history:
            # No history with this opponent: use reputation
            rep = self.reputation.get(opponent, [0, 0, 0])
            coop_rate = rep[0] / max(1, rep[2])
            if coop_rate >= self.trust_threshold:
                return True
            else:
                # If unknown and no reputation, cooperate initially
                return True
        else:
            # Compute opponent's cooperation rate with us
            coop_count = sum(opp_history)
            coop_rate = coop_count / len(opp_history)
            # Check last action
            last_action = opp_history[-1] if opp_history else True
            # If opponent cooperated last time, we cooperate with some probability
            if last_action:
                # Match cooperation but sometimes forgive if they defected recently
                if coop_rate >= self.trust_threshold:
                    return True
                else:
                    # If they are inconsistent, sometimes cooperate anyway
                    return random.random() > self.defect_bias
            else:
                # Opponent defected last time
                # With forgiveness, sometimes cooperate
                if random.random() < self.forgiveness:
                    return True
                else:
                    return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for donor and recipient
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id not in self.reputation:
                self.reputation[agent_id] = [0, 0, 0]
            self.reputation[agent_id][2] += 1
            if action == 'cooperate':
                self.reputation[agent_id][0] += 1
            else:
                self.reputation[agent_id][1] += 1

        # If we are involved, record our history with the other party
        if donor_id == self.agent_id:
            # We are donor, recipient is opponent
            if recipient_id not in self.history:
                self.history[recipient_id] = []
            self.history[recipient_id].append(donor_action == 'cooperate')
        elif recipient_id == self.agent_id:
            # We are recipient, donor is opponent
            if donor_id not in self.history:
                self.history[donor_id] = []
            self.history[donor_id].append(donor_action == 'cooperate')
        # For third-party observations, we don't update our direct history, but reputation already updated.

        # Optionally, we could also track our own actions for learning, but not needed for this strategy.

