class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.own_actions = []
        self.cooperation_threshold = 0.5
        self.memory_size = 30
        self.interaction_counts = {}
        self.last_opponent_id = None
        self.rounds_played = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        # Get reputation of opponent (default neutral)
        opp_rep = self.reputation.get(opponent, 0.0)

        # If we have history with opponent, adjust based on their behavior
        if opponent in self.interaction_counts:
            coop_count = self.interaction_counts[opponent].get('coop', 0)
            total = sum(self.interaction_counts[opponent].values())
            if total > 0:
                coop_ratio = coop_count / total
                # Blend reputation with direct observation
                opp_rep = 0.7 * opp_rep + 0.3 * (coop_ratio * 2 - 1)

        # Adaptive threshold based on population reputation
        if len(self.reputation) > 0:
            avg_rep = sum(self.reputation.values()) / len(self.reputation)
            threshold = self.cooperation_threshold + 0.2 * (avg_rep)
        else:
            threshold = self.cooperation_threshold

        # Cooperate if opponent reputation is above threshold
        if opp_rep >= threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both agents based on their actions
        # Cooperation good, defection bad

        # Donor's action
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + 0.1
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) - 0.15

        # Recipient's action (as a donor in another context)
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) + 0.1
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.0) - 0.15

        # Clamp reputation to [-1, 1]
        for agent_id in [donor_id, recipient_id]:
            if agent_id in self.reputation:
                self.reputation[agent_id] = max(-1.0, min(1.0, self.reputation[agent_id]))

        # Track own actions and interactions
        if donor_id == self.agent_id:
            self.own_actions.append(donor_action)
            if len(self.own_actions) > self.memory_size:
                self.own_actions.pop(0)
            if recipient_id not in self.interaction_counts:
                self.interaction_counts[recipient_id] = {'coop': 0, 'defect': 0}
            self.interaction_counts[recipient_id][donor_action] = self.interaction_counts[recipient_id].get(donor_action, 0) + 1

        if recipient_id == self.agent_id:
            if donor_id not in self.interaction_counts:
                self.interaction_counts[donor_id] = {'coop': 0, 'defect': 0}
            self.interaction_counts[donor_id][recipient_action] = self.interaction_counts[donor_id].get(recipient_action, 0) + 1

        # Update own cooperation threshold based on experience
        if len(self.own_actions) >= 5:
            coop_count = self.own_actions.count('cooperate')
            coop_ratio = coop_count / len(self.own_actions)
            # If we cooperated a lot and got exploited, be more cautious
            if coop_ratio > 0.7:
                self.cooperation_threshold = max(0.3, self.cooperation_threshold - 0.01)
            elif coop_ratio < 0.3:
                self.cooperation_threshold = min(0.7, self.cooperation_threshold + 0.01)

        # Decay reputation slightly to adapt to changing behavior
        for agent_id in list(self.reputation.keys()):
            if agent_id != self.agent_id:
                self.reputation[agent_id] *= 0.99

