class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {i: 0.5 for i in range(15)}
        self.recent_actions = []
        self.opponent_stats = {}
        self.pair_history = {}
        self.round = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        if self.reputation.get(opponent, 0.5) < 0.25:
            return False

        stats = self.opponent_stats.get(opponent, [0, 0])
        if stats[0] + stats[1] > 0:
            coop_rate = stats[0] / (stats[0] + stats[1])
            if coop_rate >= 0.5:
                return True
            else:
                return False

        seed = (self.agent_id * 31 + self.round * 7 + opponent * 13) % 100
        if seed < 80:
            return True
        else:
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        if donor_id == self.agent_id:
            self.recent_actions.append((recipient_id, donor_action))
            stats = self.opponent_stats.setdefault(recipient_id, [0, 0])
            if donor_action == 'cooperate':
                stats[0] += 1
            else:
                stats[1] += 1
            if len(self.recent_actions) > 20:
                self.recent_actions.pop(0)
        elif recipient_id == self.agent_id:
            self.recent_actions.append((donor_id, recipient_action))
            stats = self.opponent_stats.setdefault(donor_id, [0, 0])
            if donor_action == 'cooperate':
                stats[0] += 1
            else:
                stats[1] += 1
            if len(self.recent_actions) > 20:
                self.recent_actions.pop(0)

        pair_key = (donor_id, recipient_id)
        hist = self.pair_history.setdefault(pair_key, [])
        hist.append((donor_action, recipient_action))
        if len(hist) > 10:
            hist.pop(0)

        alpha = 0.1
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + alpha * (1.0 - self.reputation.get(donor_id, 0.5))
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - alpha * self.reputation.get(donor_id, 0.5)
        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + alpha * (1.0 - self.reputation.get(recipient_id, 0.5))
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - alpha * self.reputation.get(recipient_id, 0.5)

        self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))
        self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

