class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.scores = {}  # opponent_id -> score (higher = more cooperative)
        self.interactions = {}  # opponent_id -> count of interactions
        self.my_history = []  # list of my actions
        self.opponent_history = {}  # opponent_id -> list of actions
        self.generation = 0
        self.rounds_this_gen = 0
        self.coop_count = 0
        self.defect_count = 0
        self.trust_threshold = 0.0
        self.alpha = 0.3  # learning rate for reputation
        self.epsilon = 0.05  # exploration probability

    def decide(self) -> bool:
        # If no opponent info, cooperate initially
        if not hasattr(self, '_ctx_opponent_id'):
            return True
        opp = self._ctx_opponent_id
        # Update generation tracking (approximate)
        self.rounds_this_gen += 1
        if self.rounds_this_gen > 30:
            self.rounds_this_gen = 1
            self.generation += 1

        # Exploration
        if random.random() < self.epsilon:
            return random.random() < 0.8

        # Get reputation score for this opponent
        score = self.scores.get(opp, 0.0)
        # Adjust based on our own history: if we've cooperated a lot, be more trusting
        if self.interactions.get(opp, 0) == 0:
            # No history: default to cooperation if we have a good overall reputation
            if self.coop_count > self.defect_count * 2:
                return True
            return True  # default cooperate

        # More nuanced: if opponent has high score, cooperate; if low, defect
        if score > 0.2:
            return True
        elif score < -0.2:
            return False
        else:
            # Neutral: use tit-for-tat with some forgiveness
            last_opp_action = self.opponent_history.get(opp, [])
            if last_opp_action:
                last = last_opp_action[-1]
                if last == 'defect':
                    # Forgive if we have cooperated a lot overall
                    if self.coop_count > self.defect_count * 3:
                        return True
                    return False
                else:
                    return True
            return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update our own history if we are involved
        if donor_id == self.agent_id:
            self.my_history.append(donor_action)
            if donor_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            # Also update opponent's reputation based on their action
            if recipient_id != self.agent_id:
                self._update_scores(recipient_id, recipient_action)
        elif recipient_id == self.agent_id:
            self.my_history.append(recipient_action)
            if recipient_action == 'cooperate':
                self.coop_count += 1
            else:
                self.defect_count += 1
            # Update donor's reputation
            if donor_id != self.agent_id:
                self._update_scores(donor_id, donor_action)
        else:
            # Third-party observation: update both reputations
            self._update_scores(donor_id, donor_action)
            self._update_scores(recipient_id, recipient_action)

    def _update_scores(self, agent_id: int, action: str) -> None:
        # Simple reputation: cooperate +1, defect -1, with learning rate
        if action == 'cooperate':
            delta = 1.0
        else:
            delta = -1.0
        # Decay old scores slightly
        old = self.scores.get(agent_id, 0.0)
        new = old * (1 - self.alpha) + self.alpha * delta
        self.scores[agent_id] = new
        # Update interaction count
        self.interactions[agent_id] = self.interactions.get(agent_id, 0) + 1
        # Track opponent's actions for tit-for-tat
        if agent_id != self.agent_id:
            if agent_id not in self.opponent_history:
                self.opponent_history[agent_id] = []
            self.opponent_history[agent_id].append(action)

