        self.reputation = {}
        self.personal_history = {}
        self.cooperation_count = 0
        self.defection_count = 0
        self.generation = 0
        self.round = 0
        self._ctx_opponent_id = None
        self.trust_threshold = 0.45
        self.memory_limit = 30
        self.forgiveness = 0.1
        self.epsilon = 0.1

