        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        opp_rep = self.reputation.get(opponent, 0.5)
        hist = self.personal_history.get(opponent, [])
        if len(hist) >= 5:
            recent = hist[-5:]
            coop_freq = recent.count('cooperate') / len(recent)
        else:
            coop_freq = 0.5

        combined = 0.6 * opp_rep + 0.4 * coop_freq

        if combined < self.trust_threshold:
            if random.random() < self.forgiveness:
                return True
            return False
        else:
            if random.random() < self.epsilon:
                return False
            return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        if self.round % 30 == 1:
            self.generation += 1

        delta = 0.1
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + delta
            else:
                self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - delta
            self.reputation[donor_id] = max(0.0, min(1.0, self.reputation[donor_id]))

        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + delta
            else:
                self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - delta
            self.reputation[recipient_id] = max(0.0, min(1.0, self.reputation[recipient_id]))

