class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Track cooperation/defection counts per opponent
        self.opponent_stats = {}
        # Track own actions history (last actions)
        self.own_history = []
        # Track global observations of others (reputation)
        self.reputation = {}
        # Simple memory of recent opponent behavior
        self.recent_opponent_actions = {}
        # Cooperation threshold
        self.coop_threshold = 0.5
        # Small exploration probability
        self.explore_prob = 0.02
        # Generosity factor
        self.generosity = 0.1

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True  # default cooperate if no opponent info

        # Get opponent's stats
        stats = self.opponent_stats.get(opponent, {"coop": 0, "defect": 0, "n": 0})
        if stats["n"] == 0:
            # No history with this opponent: cooperate with high probability
            return random.random() > self.explore_prob

        coop_rate = stats["coop"] / stats["n"]
        # Use a tit-for-tat-like strategy with forgiveness
        if coop_rate >= self.coop_threshold:
            # Cooperate if opponent has been cooperative
            return random.random() > self.explore_prob
        else:
            # Defect if opponent has been mostly defecting
            return random.random() < self.explore_prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update opponent stats if we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opponent = recipient_id if donor_id == self.agent_id else donor_id
            if opponent != self.agent_id:
                # Determine which action opponent took
                if donor_id == self.agent_id:
                    opponent_action = recipient_action
                else:
                    opponent_action = donor_action
                stats = self.opponent_stats.setdefault(opponent, {"coop": 0, "defect": 0, "n": 0})
                if opponent_action == "cooperate":
                    stats["coop"] += 1
                else:
                    stats["defect"] += 1
                stats["n"] += 1

        # Update reputation of observed agents (third-party)
        # Track cooperation rate for each agent
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            rep = self.reputation.setdefault(agent_id, {"coop": 0, "defect": 0, "n": 0})
            if action == "cooperate":
                rep["coop"] += 1
            else:
                rep["defect"] += 1
            rep["n"] += 1

