        self.total_count = {}
        self.my_coop_count = {}
        self.my_total_count = {}
        self.recent_outcomes = []
        self.round_count = 0

    def decide(self) -> bool:
        self.round_count += 1
        opp = self._ctx_opponent_id
        self.opponent_id = opp

        opp_coop_prob = 0.5
        if opp in self.total_count and self.total_count[opp] > 0:
            opp_coop_prob = self.coop_count[opp] / self.total_count[opp]

        my_coop_rate = 0.5
        if opp in self.my_total_count and self.my_total_count[opp] > 0:
            my_coop_rate = self.my_coop_count[opp] / self.my_total_count[opp]

        opp_rep = self.reputation.get(opp, 0.5)
        blended = 0.7 * opp_coop_prob + 0.3 * opp_rep

        recent_exploit = 0
        recent_coop = 0
        for outcome in self.recent_outcomes[-10:]:
            my_a, opp_a = outcome
            if my_a and not opp_a:
                recent_exploit += 1
            if my_a and opp_a:
                recent_coop += 1

        exploit_penalty = 0.0
        if len(self.recent_outcomes) >= 5:
            exploit_rate = recent_exploit / max(1, len(self.recent_outcomes))
            if exploit_rate > 0.3:
                exploit_penalty = 0.1 * min(1.0, (exploit_rate - 0.3) / 0.7)

        coop_bonus = 0.0
        if len(self.recent_outcomes) >= 5:
            mutual_rate = recent_coop / max(1, len(self.recent_outcomes))
            if mutual_rate > 0.5:
                coop_bonus = 0.1 * min(1.0, (mutual_rate - 0.5) / 0.5)

        prob_coop = blended - exploit_penalty + coop_bonus
        prob_coop = max(0.0, min(1.0, prob_coop))

        seed = (self.agent_id * 1000 + self.round_count * 7) % 100
        threshold = prob_coop * 100
        return seed < threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        delta = 0.1
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + delta
