        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + delta
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - delta

        for pid in [donor_id, recipient_id]:
            self.reputation[pid] = max(0.0, min(1.0, self.reputation[pid]))

        if donor_id == self.agent_id:
            my_action = donor_action == 'cooperate'
            opp_action = recipient_action == 'cooperate'
            opp = recipient_id
            self.recent_outcomes.append((my_action, opp_action))
            self.my_total_count[opp] = self.my_total_count.get(opp, 0) + 1
