class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_actions = []
        self.opponent_actions = {}
        self.self_reputation = 0.5
        self.round_count = 0
        self.generation = 0
        self.coop_streak = 0
        self.defect_streak = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return True

        # Get opponent's reputation, default to neutral
        opp_rep = self.reputation.get(opponent, 0.5)

        # Adjust based on opponent's recent actions against us
        opp_actions = self.opponent_actions.get(opponent, [])
        if len(opp_actions) >= 3:
            recent = opp_actions[-3:]
            coop_count = recent.count('cooperate')
            if coop_count == 0:
                opp_rep -= 0.3
            elif coop_count == 1:
                opp_rep -= 0.1
            elif coop_count == 2:
                opp_rep += 0.1
            else:
                opp_rep += 0.2

        # Self-reputation adjustment
        adjusted_rep = (opp_rep + self.self_reputation) / 2

        # Probability of cooperating
        coop_prob = adjusted_rep

        # Slight randomness to avoid being too predictable
        if random.random() < 0.05:
            return random.random() < 0.5

        # If we've been cooperating a lot and opponent defects, be more cautious
        if self.coop_streak >= 5 and opp_rep < 0.4:
            coop_prob -= 0.1

        # If we've been defecting a lot, try to rebuild cooperation
        if self.defect_streak >= 3:
            coop_prob += 0.2

        return random.random() < coop_prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update round/generation tracking
        self.round_count += 1
        if self.round_count % 30 == 0:
            self.generation += 1

        # Update self reputation based on our own actions
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.self_reputation = min(1.0, self.self_reputation + 0.05)
                self.coop_streak += 1
                self.defect_streak = 0
            else:
                self.self_reputation = max(0.0, self.self_reputation - 0.05)
                self.defect_streak += 1
                self.coop_streak = 0

        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.self_reputation = min(1.0, self.self_reputation + 0.02)
            else:
                self.self_reputation = max(0.0, self.self_reputation - 0.02)

        # Update opponent action history
        if donor_id == self.agent_id:
            opp_id = recipient_id
            opp_action = recipient_action
        elif recipient_id == self.agent_id:
            opp_id = donor_id
            opp_action = donor_action
        else:
            opp_id = None
            opp_action = None

        if opp_id is not None:
            if opp_id not in self.opponent_actions:
                self.opponent_actions[opp_id] = []
            self.opponent_actions[opp_id].append(opp_action)
            if len(self.opponent_actions[opp_id]) > 20:
                self.opponent_actions[opp_id].pop(0)

        # Update reputation based on observed interactions
        # Reward cooperation, punish defection
        if donor_action == 'cooperate' and recipient_action == 'cooperate':
            self._update_rep(donor_id, 0.05)
            self._update_rep(recipient_id, 0.05)
        elif donor_action == 'cooperate' and recipient_action == 'defect':
            self._update_rep(donor_id, 0.02)
            self._update_rep(recipient_id, -0.1)
        elif donor_action == 'defect' and recipient_action == 'cooperate':
            self._update_rep(donor_id, -0.1)
            self._update_rep(recipient_id, 0.02)
        else:  # both defect
            self._update_rep(donor_id, -0.05)
            self._update_rep(recipient_id, -0.05)

        # Periodic reputation decay to keep values in check
        if self.round_count % 100 == 0:
            for key in list(self.reputation.keys()):
                self.reputation[key] *= 0.95

    def _update_rep(self, agent_id: int, delta: float) -> None:
        if agent_id == self.agent_id:
            return  # Don't update self through this path
        current = self.reputation.get(agent_id, 0.5)
        self.reputation[agent_id] = max(0.0, min(1.0, current + delta))

