class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None

        # Reputation tracking
        self.reputation = {}  # agent_id -> running score
        self.interaction_count = {}  # agent_id -> times we've been paired
        self.last_action = {}  # agent_id -> last action we saw from them (if any)
        self.observed_coop = {}  # agent_id -> count of observed cooperations
        self.observed_defect = {}  # agent_id -> count of observed defections

        # For partner-specific memory (what we did with each)
        self.my_last_action_towards = {}
        self.their_last_action_towards_me = {}

        # For self-assessment
        self.my_coop_count = 0
        self.my_defect_count = 0

        # For forgiveness / noise
        self.noise = 0.05  # small probability to cooperate even if defecting

        # To avoid being too exploitable, track overall defection rate of others
        self.global_coop_seen = 0
        self.global_defect_seen = 0

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        if opp is None:
            return True  # should not happen, but safe

        # Initialize reputation if unseen
        if opp not in self.reputation:
            self.reputation[opp] = 0.0
        if opp not in self.interaction_count:
            self.interaction_count[opp] = 0

        # If we've never interacted or observed this opponent much, be cooperative initially
        total_obs = self.observed_coop.get(opp, 0) + self.observed_defect.get(opp, 0)
        if total_obs < 3 and self.interaction_count.get(opp, 0) == 0:
            # Start cooperative, but with a slight chance to test
            return random.random() > 0.1

        # Strategy: Tit-for-tat with forgiveness, based on reputation
        # If opponent has defected more than cooperated in our observations, defect
        coop = self.observed_coop.get(opp, 0)
        defec = self.observed_defect.get(opp, 0)
        if coop + defec > 0:
            coop_ratio = coop / (coop + defec)
            if coop_ratio < 0.3:
                # Mostly defector, defect
                return random.random() > self.noise
            elif coop_ratio < 0.6:
                # Mixed, reciprocate their last action if we have it
                last = self.their_last_action_towards_me.get(opp)
                if last is not None:
                    return last if random.random() > self.noise else True
                else:
                    # No direct last action, use reputation
                    return random.random() > self.noise
            else:
                # Mostly cooperative, cooperate
                return True
        else:
            # No observations, use direct interaction history
            last_their = self.their_last_action_towards_me.get(opp)
            if last_their is None:
                return True
            else:
                # Tit-for-tat with occasional forgiveness
                if last_their:
                    return True
                else:
                    # They defected last time, forgive with small probability
                    return random.random() > 0.15

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update global counts
        if donor_action == 'cooperate':
            self.global_coop_seen += 1
        else:
            self.global_defect_seen += 1
        if recipient_action == 'cooperate':
            self.global_coop_seen += 1
        else:
            self.global_defect_seen += 1

        # Update per-agent observation counts
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue  # don't track ourselves in observations
            if action == 'cooperate':
                self.observed_coop[agent_id] = self.observed_coop.get(agent_id, 0) + 1
            else:
                self.observed_defect[agent_id] = self.observed_defect.get(agent_id, 0) + 1

        # Update reputation (simple additive: +1 for cooperate, -1 for defect)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.0
            if action == 'cooperate':
                self.reputation[agent_id] += 1.0
            else:
                self.reputation[agent_id] -= 1.0

        # Handle self-judgment events
        if donor_id == self.agent_id:
            self.my_coop_count += (donor_action == 'cooperate')
            self.my_defect_count += (donor_action == 'defect')
            # Record what we did to recipient
            self.my_last_action_towards[recipient_id] = (donor_action == 'cooperate')
            # Also record recipient's action towards us
            self.their_last_action_towards_me[recipient_id] = (recipient_action == 'cooperate')
        if recipient_id == self.agent_id:
            self.my_coop_count += (recipient_action == 'cooperate')
            self.my_defect_count += (recipient_action == 'defect')
            self.my_last_action_towards[donor_id] = (recipient_action == 'cooperate')
            self.their_last_action_towards_me[donor_id] = (donor_action == 'cooperate')

        # Update interaction count if we are involved
        if donor_id == self.agent_id and recipient_id != self.agent_id:
            self.interaction_count[recipient_id] = self.interaction_count.get(recipient_id, 0) + 1
        if recipient_id == self.agent_id and donor_id != self.agent_id:
            self.interaction_count[donor_id] = self.interaction_count.get(donor_id, 0) + 1

