                self.my_coop_count[opp] = self.my_coop_count.get(opp, 0) + 1
            self.total_count[opp] = self.total_count.get(opp, 0) + 1
            if opp_action:
                self.coop_count[opp] = self.coop_count.get(opp, 0) + 1
        elif recipient_id == self.agent_id:
            my_action = recipient_action == 'cooperate'
            opp_action = donor_action == 'cooperate'
            opp = donor_id
            self.recent_outcomes.append((my_action, opp_action))
            self.my_total_count[opp] = self.my_total_count.get(opp, 0) + 1
