import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, store:
        # 0 = no info yet, 1 = good (cooperated with someone who cooperated),
        # -1 = bad (defected against a cooperator)
        self.reputation = {}
        # Track cooperation counts for self and others
        self.coop_count = {}
        self.defect_count = {}
        self.total_actions = {}
        # Track recent behavior of each agent (sliding window of last 10 actions)
        self.recent_actions = {}
        # Personal experience with each opponent (cooperation rate)
        self.personal_coop_rate = {}
        self.personal_encounters = {}
        # Generosity parameter: how much we forgive bad reputation
        self.generosity = 0.8
        # Own recent cooperation rate (for tit-for-tat style)
        self.own_recent_coops = []
        self.own_recent_defects = []
        self.current_round = 0
        # Opponent context
        self._ctx_opponent_id = None

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True  # safe default

        # Get opponent's reputation and cooperation history
        opp_reputation = self.reputation.get(opponent, 0)
        opp_coop_rate = 0.5  # default
        if opponent in self.total_actions:
            total = self.total_actions.get(opponent, 0)
            coop = self.coop_count.get(opponent, 0)
            if total > 0:
                opp_coop_rate = coop / total

        # Personal experience with this opponent
        personal_rate = 0.5
        if opponent in self.personal_encounters:
            total_enc = self.personal_encounters[opponent]
            if total_enc > 0:
                coop_enc = self.personal_coop_rate.get(opponent, 0)
                personal_rate = coop_enc / total_enc

        # Combine reputation, global cooperation rate, and personal experience
        # Weighted average
        combined_score = (0.4 * (0.5 + 0.5 * opp_reputation) +
                          0.3 * opp_coop_rate +
                          0.3 * personal_rate)

        # Apply generosity: if opponent has bad reputation, we might still cooperate with some probability
        if opp_reputation < 0:
            # Forgive with probability based on generosity
            if random.random() < self.generosity:
                combined_score = max(combined_score, 0.4)

        # Tit-for-tat component: if opponent defected against us recently, be more cautious
        if self.recent_actions and opponent in self.recent_actions:
            recent = self.recent_actions[opponent]
            if recent and recent[-1] == 'defect':
                # Last action was defection, reduce cooperation probability
                combined_score *= 0.7

        # Decide based on threshold
        threshold = 0.5
        # Slight tendency to cooperate initially to build trust
        if self.current_round < 5:
            threshold = 0.3

        # Add small noise to avoid predictability
        noise = random.uniform(-0.05, 0.05)
        return (combined_score + noise) > threshold

    def observe(self, donor_id: int, donor_action: str,
                recipient_id: int, recipient_action: str) -> None:
        # Update own action tracking
        if donor_id == self.agent_id:
            self.current_round += 1
            if donor_action == 'cooperate':
                self.own_recent_coops.append(1)
            else:
                self.own_recent_defects.append(1)
            # Keep window size
            if len(self.own_recent_coops) + len(self.own_recent_defects) > 10:
                if self.own_recent_coops:
                    self.own_recent_coops.pop(0)
                elif self.own_recent_defects:
                    self.own_recent_defects.pop(0)

        if recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.own_recent_coops.append(1)
            else:
                self.own_recent_defects.append(1)
            # Keep window size
            if len(self.own_recent_coops) + len(self.own_recent_defects) > 10:
                if self.own_recent_coops:
                    self.own_recent_coops.pop(0)
                elif self.own_recent_defects:
                    self.own_recent_defects.pop(0)

        # Update reputation for both actors
        # We judge based on action against the other's action
        for actor_id, actor_action, other_action in [
            (donor_id, donor_action, recipient_action),
            (recipient_id, recipient_action, donor_action)
        ]:
            if actor_id == self.agent_id:
                continue  # Don't judge ourselves (but we track our own actions above)

            # Update action counts
            if actor_id not in self.total_actions:
                self.total_actions[actor_id] = 0
                self.coop_count[actor_id] = 0
                self.defect_count[actor_id] = 0
                self.recent_actions[actor_id] = []
                self.personal_encounters[actor_id] = 0
                self.personal_coop_rate[actor_id] = 0

            self.total_actions[actor_id] += 1
            if actor_action == 'cooperate':
                self.coop_count[actor_id] += 1
            else:
                self.defect_count[actor_id] += 1

            # Update recent actions
            self.recent_actions[actor_id].append(actor_action)
            if len(self.recent_actions[actor_id]) > 10:
                self.recent_actions[actor_id].pop(0)

            # Update reputation: cooperate with cooperator = good, defect against cooperator = bad
            # Defect against defector = neutral, cooperate with defector = neutral (or slightly good?)
            if actor_action == 'cooperate' and other_action == 'cooperate':
                # Mutual cooperation: good
                current_rep = self.reputation.get(actor_id, 0)
                self.reputation[actor_id] = min(1, current_rep + 0.1)
            elif actor_action == 'defect' and other_action == 'cooperate':
                # Defection against a cooperator: bad
                current_rep = self.reputation.get(actor_id, 0)
                self.reputation[actor_id] = max(-1, current_rep - 0.2)
            elif actor_action == 'defect' and other_action == 'defect':
                # Mutual defection: neutral (slightly bad maybe)
                current_rep = self.reputation.get(actor_id, 0)
                self.reputation[actor_id] = max(-1, current_rep - 0.05)
            elif actor_action == 'cooperate' and other_action == 'defect':
                # Cooperating with a defector: slightly bad (being exploited)
                current_rep = self.reputation.get(actor_id, 0)
                self.reputation[actor_id] = max(-1, current_rep - 0.05)

            # Personal experience: if this actor was our opponent in a pair
            if actor_id == self._ctx_opponent_id or donor_id == actor_id or recipient_id == actor_id:
                # Only update personal experience if we were directly involved
                if donor_id == self.agent_id or recipient_id == self.agent_id:
                    # We were in the pair, update personal experience for the other
                    other_id = donor_id if donor_id != self.agent_id else recipient_id
                    if other_id == actor_id:
                        self.personal_encounters[actor_id] += 1
                        if actor_action == 'cooperate':
                            self.personal_coop_rate[actor_id] += 1

