import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each other agent, keep counts of cooperative and defective actions observed
        self.reputation = {}  # agent_id -> [coop_count, defect_count]
        # Track own interactions: for each opponent, store last action taken by self and opponent
        self.own_history = {}  # opponent_id -> list of (my_action, their_action)
        # Track overall cooperation tendency of each agent (smoothed)
        self.coop_tendency = {}  # agent_id -> float in [0,1]
        # Track recent cooperation rate of self for adaptive threshold
        self.self_coop_rate = 0.5
        # Memory of recent interactions for forgiveness/retaliation
        self.recent_opponent_coop = {}  # opponent_id -> last action bool
        # Number of generations seen (optional, not used)
        self.generation = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None or opponent == self.agent_id:
            # No opponent or self-play (shouldn't happen), default cooperate
            return True

        # If we have history with this opponent, use tit-for-tat with forgiveness
        if opponent in self.own_history and len(self.own_history[opponent]) > 0:
            last_their = self.own_history[opponent][-1][1]
            # Tit-for-tat: retaliate if they defected last time, but with occasional forgiveness
            if last_their == 'defect':
                # 15% chance to forgive and cooperate to avoid endless retaliation
                if random.random() < 0.15:
                    return True
                else:
                    return False
            else:
                return True
        else:
            # No history: base decision on reputation of opponent
            if opponent in self.reputation:
                coop, defect = self.reputation[opponent]
                total = coop + defect
                if total > 0:
                    coop_ratio = coop / total
                    # Cooperate if reputation is decent, but be cautious if unknown or bad
                    if coop_ratio >= 0.5:
                        return True
                    else:
                        # Defect against known defectors, but with some chance to probe
                        if random.random() < 0.1:
                            return True  # Probe cooperation occasionally
                        return False
                else:
                    # No observations: cooperate initially (optimistic)
                    return True
            else:
                # Unknown agent: cooperate initially
                return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for donor and recipient (third-party observations)
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue  # Skip self in reputation
            if agent_id not in self.reputation:
                self.reputation[agent_id] = [0, 0]
            if action == 'cooperate':
                self.reputation[agent_id][0] += 1
            else:
                self.reputation[agent_id][1] += 1
            # Update smoothed tendency
            coop, defect = self.reputation[agent_id]
            total = coop + defect
            if total > 0:
                # Exponential moving average with weight 0.1 for new obs
                new_ratio = coop / total
                old = self.coop_tendency.get(agent_id, 0.5)
                self.coop_tendency[agent_id] = 0.9 * old + 0.1 * new_ratio

        # If this is self-judgment (we are donor or recipient), update own history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_id = recipient_id
                their_action = recipient_action
            else:
                my_action = recipient_action
                other_id = donor_id
                their_action = donor_action
            if other_id not in self.own_history:
                self.own_history[other_id] = []
            self.own_history[other_id].append((my_action, their_action))
            # Keep history bounded (last 10 interactions per opponent)
            if len(self.own_history[other_id]) > 10:
                self.own_history[other_id] = self.own_history[other_id][-10:]
            # Update recent opponent coop for potential use
            self.recent_opponent_coop[other_id] = (their_action == 'cooperate')
            # Update self cooperation rate (moving average)
            self.self_coop_rate = 0.9 * self.self_coop_rate + 0.1 * (1 if my_action == 'cooperate' else 0)

