class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation tracking: for each agent, count of observed cooperative and defective actions
        self.coop_counts = {}
        self.defect_counts = {}
        # Track personal interactions: for each opponent, list of outcomes from our perspective
        # outcome: (we_cooperated, opponent_cooperated) as booleans
        self.personal_history = {}
        # Track our recent actions to build a simple strategy
        self.my_recent_actions = []
        # Cooperation threshold for reputation: if coop ratio > threshold, consider them 'good'
        self.reputation_threshold = 0.5
        # Memory window for reputation (use recent observations)
        self.reputation_memory = 50

    def _get_reputation(self, agent_id: int) -> float:
        """Return estimated cooperation probability of agent based on observed actions."""
        c = self.coop_counts.get(agent_id, 0)
        d = self.defect_counts.get(agent_id, 0)
        total = c + d
        if total == 0:
            return 0.5  # unknown, neutral
        # Use a weighted average with prior to avoid extreme values
        return (c + 1) / (total + 2)

    def _record_observation(self, actor_id: int, action: str) -> None:
        """Record an observed action by an actor."""
        if action == 'cooperate':
            self.coop_counts[actor_id] = self.coop_counts.get(actor_id, 0) + 1
        else:
            self.defect_counts[actor_id] = self.defect_counts.get(actor_id, 0) + 1
        # Optional: cap memory to prevent unbounded growth (but counts are fine)

    def _record_personal(self, opponent_id: int, my_coop: bool, opp_coop: bool) -> None:
        """Record a personal interaction outcome."""
        if opponent_id not in self.personal_history:
            self.personal_history[opponent_id] = []
        # Keep last 5 interactions for quick pattern
        hist = self.personal_history[opponent_id]
        hist.append((my_coop, opp_coop))
        if len(hist) > 5:
            hist.pop(0)

    def _has_retaliated_recently(self, opponent_id: int) -> bool:
        """Check if we have recently defected against this opponent after they defected."""
        hist = self.personal_history.get(opponent_id, [])
        # Look at last 3 interactions: if we defected after they defected, consider retaliation active
        for my_coop, opp_coop in hist[-3:]:
            if not my_coop and not opp_coop:
                return True
        return False

    def decide(self) -> bool:
        # Get opponent id (set by framework)
        opp = self._ctx_opponent_id
        # If no opponent (shouldn't happen), cooperate
        if opp is None:
            return True

        # Get reputation of opponent
        rep = self._get_reputation(opp)

        # Check personal history: if opponent has been cooperative in most recent interactions, be cooperative
        hist = self.personal_history.get(opp, [])
        if len(hist) >= 2:
            recent_coop = sum(1 for _, opp_coop in hist[-2:] if opp_coop)
            if recent_coop == 2:
                return True  # Both recent interactions cooperative -> reciprocate
            if recent_coop == 0:
                return False  # Both defected -> defect

        # If we have a strong reputation (high coop probability), cooperate; if low, defect
        if rep > 0.7:
            return True
        if rep < 0.3:
            return False

