class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        # Reputation tracking: dict mapping agent_id -> [cooperate_count, defect_count]
        self.reputation = {}
        # Track personal interactions: dict mapping opponent_id -> list of (my_action, their_action)
        self.interactions = {}
        # Track how often we have cooperated/defected overall
        self.total_coop = 0
        self.total_defect = 0
        # Track recent outcomes for adaptive behavior
        self.recent_results = []  # list of (my_action, opponent_action) from last few rounds
        self.round_count = 0

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        # Default to cooperate if no info
        if opponent is None:
            return True

        # Get opponent reputation
        coop, defect = self.reputation.get(opponent, (0, 0))
        total_obs = coop + defect
        # Estimate their cooperation probability from reputation
        if total_obs > 0:
            est_coop_prob = coop / total_obs
        else:
            est_coop_prob = 0.5  # uncertain

        # Personal history adjustment
        personal = self.interactions.get(opponent, [])
        if personal:
            # Weight recent personal interactions more
            recent_personal = personal[-5:]
            my_coop = sum(1 for my, their in recent_personal if my)
            their_coop = sum(1 for my, their in recent_personal if their)
            n = len(recent_personal)
            # Combine personal and reputation estimates
            if n > 0:
                personal_prob = their_coop / n
                # Blend: 60% personal, 40% reputation if we have personal data
                blended = 0.6 * personal_prob + 0.4 * est_coop_prob
            else:
                blended = est_coop_prob
        else:
            blended = est_coop_prob

        # Defensive strategy: cooperate unless we think they defect often
        # Threshold: cooperate if estimated coop prob > 0.4
        # But also be more forgiving early game, more strict later
        # Simple tit-for-tat with forgiveness
        if personal:
            # If last interaction was their defection, defect (tit-for-tat)
            last_their = personal[-1][1]
            if not last_their:
                # But forgive with some probability if they usually cooperate
                if blended > 0.6:
                    # Forgive with probability 0.3
                    if random.random() < 0.3:
                        return True
                    else:
                        return False
                else:
                    return False
            else:
                # They cooperated last time, cooperate
                return True
        else:
            # No personal history: use reputation
            # Be cautious: cooperate if reputation suggests > 0.5 coop prob
            # But if unknown, cooperate initially
            if total_obs == 0:
                return True
            else:
                return blended >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
