class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.my_actions = []
        self.encounters = {}
        self.generosity = 0.5
        self.forget = 0.95
        self.total_coops = 0
        self.total_defs = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        if opponent is None:
            return random.random() < self.generosity

        rep = self.reputation.get(opponent, [0, 0])
        coops, defs = rep
        total = coops + defs
        if total == 0:
            return random.random() < self.generosity

        coop_ratio = coops / total
        threshold = 0.55
        if coop_ratio > threshold:
            return True
        else:
            return False

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self._update_rep(donor_id, donor_action)
        self._update_rep(recipient_id, recipient_action)

        if donor_id == self.agent_id:
            self.my_actions.append(donor_action == 'cooperate')
            if donor_action == 'cooperate':
                self.total_coops += 1
            else:
                self.total_defs += 1
            self.encounters.setdefault(recipient_id, []).append(
                (donor_action == 'cooperate', recipient_action == 'cooperate')
            )
        elif recipient_id == self.agent_id:
            self.my_actions.append(recipient_action == 'cooperate')
            if recipient_action == 'cooperate':
                self.total_coops += 1
            else:
                self.total_defs += 1
            self.encounters.setdefault(donor_id, []).append(
                (recipient_action == 'cooperate', donor_action == 'cooperate')
            )

        if len(self.my_actions) > 0:
            recent = self.my_actions[-10:]
            recent_coop = sum(recent)
            recent_ratio = recent_coop / len(recent)
            self.generosity = 0.9 * self.generosity + 0.1 * recent_ratio

    def _update_rep(self, agent_id: int, action: str) -> None:
        rep = self.reputation.setdefault(agent_id, [0, 0])
        rep[0] = int(rep[0] * self.forget)
        rep[1] = int(rep[1] * self.forget)
        if action == 'cooperate':
            rep[0] += 1
        else:
            rep[1] += 1

