class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.observation_count = {}
        self.my_actions = []
        self.memory = {}
        self.coop_threshold = 0.5
        self.self_weight = 1.0
        self.rounds_played = 0

    def decide(self) -> bool:
        opponent = getattr(self, "_ctx_opponent_id", None)
        if opponent is None:
            return True

        history = self.memory.get(opponent, [])
        if history:
            opp_coop_rate = sum(1 for _, a in history if a == "cooperate") / len(history)
            recent = history[-5:] if len(history) >= 5 else history
            recent_coop = sum(1 for _, a in recent if a == "cooperate") / len(recent)
            trust_score = 0.6 * opp_coop_rate + 0.4 * recent_coop
            if history and history[-1][1] == "cooperate":
                return True
            if trust_score < 0.4:
                return False
            return random.random() < trust_score

        rep = self.reputation.get(opponent, 0.5)
        count = self.observation_count.get(opponent, 0)
        if count == 0:
            return True
        if rep > self.coop_threshold:
            return True
        else:
            return False

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        for agent_id, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent_id == self.agent_id:
                continue
            score = 1.0 if action == "cooperate" else 0.0
            if agent_id not in self.reputation:
                self.reputation[agent_id] = 0.0
                self.observation_count[agent_id] = 0
            self.observation_count[agent_id] += 1
            n = self.observation_count[agent_id]
            alpha = 0.2
            self.reputation[agent_id] = (1 - alpha) * self.reputation[agent_id] + alpha * score

        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                opp_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                opp_action = donor_action
                opp_id = donor_id
            if opp_id not in self.memory:
                self.memory[opp_id] = []
            self.memory[opp_id].append((my_action, opp_action))
            if len(self.memory[opp_id]) > 30:
                self.memory[opp_id] = self.memory[opp_id][-30:]
            self.rounds_played += 1

        all_reps = list(self.reputation.values())
        if len(all_reps) > 5:
            avg_rep = sum(all_reps) / len(all_reps)
            self.coop_threshold = 0.4 + 0.1 * (avg_rep - 0.5)

