        if opp not in self.interaction_count:
            self.interaction_count[opp] = 0
        if opp not in self.defection_count:
            self.defection_count[opp] = 0
        if opp not in self._trust:
            self._trust[opp] = 0.5
        if opp not in self._opponent_history:
            self._opponent_history[opp] = []

        # Adaptive strategy based on opponent reputation and history
        if self.interaction_count[opp] < 3:
            # Early: cooperate to build trust, but with slight caution
