        self.own_actions = []  # list of (opponent_id, action, opponent_action)
        self.round_num = 0
        self.generation_num = 0
        self.last_opponent_action = None
        # For strategy adaptation: keep track of performance against each opponent
        self.opponent_performance = {}  # opponent_id -> list of (my_action, their_action)
        self.trust_threshold = 0.6  # initial threshold for cooperation based on reputation
        self.cooperation_bias = 0.5  # probability of cooperating with unknown agents
        self.learning_rate = 0.05

    def decide(self) -> bool:
        # Increment round counter (called once per round before decision)
        self.round_num += 1
        if self.round_num % 30 == 1:  # new generation
            self.generation_num += 1
            # Adjust trust threshold based on overall experience
            if self.generation_num > 1:
                self._adapt_threshold()

        opp = self._ctx_opponent_id
        self.opponent_id = opp
