        if opp in self.opponent_performance:
            history = self.opponent_performance[opp]
            if len(history) >= 2:
                # Recent behavior: check last few interactions
                recent = history[-3:]
                coop_rate = sum(1 for _, a in recent if a == 'cooperate') / len(recent)
                if coop_rate >= 0.5:
                    # Opponent tends to cooperate: be cooperative
                    return True
                elif coop_rate <= 0.2:
                    # Opponent tends to defect: defect
                    return False
                else:
                    # Mixed: use tit-for-tat with forgiveness
                    if history and history[-1][1] == 'defect':
                        return False
                    else:
                        return True
        # No direct history: use reputation
        if opp in self.reputation:
            coop_count, total = self.reputation[opp]
            if total > 0:
                coop_rate = coop_count / total
                if coop_rate > self.trust_threshold:
                    return True
                else:
                    return False
