        self.agent_id = agent_id
        # Reputation scores per agent: initial neutral 0, range roughly -10 to 10
        self.reputation = {}
        # Track cooperation counts for each agent
        self.coop_counts = {}
        self.defect_counts = {}
        # Track my own interactions: for each opponent, list of (my_action, their_action)
        self.history = {}
        # Global round counter
        self.round_num = 0
        # My recent action in last round (to use in decisions if needed)
        self.last_my_action = None
        # Baseline threshold: adjust over time
        self.threshold = 0.0
        self.total_observed = 0

    def _get_reputation(self, agent_id):
        return self.reputation.get(agent_id, 0.0)

    def _set_reputation(self, agent_id, value):
        # Clamp to reasonable range
        self.reputation[agent_id] = max(-10.0, min(10.0, value))

    def _update_reputation(self, donor_id, donor_action, recipient_id, recipient_action):
        # Update reputation based on observed action
        # Cooperation is good, defection is bad
        # Also consider reciprocity: if donor cooperated and recipient defected, donor is a victim
        self.total_observed += 1
        if donor_id != self.agent_id:
            if donor_action == 'cooperate':
                # Cooperation increases reputation slightly, but more if the other defected
                delta = 0.2
                if recipient_action == 'defect':
                    delta = 0.5  # They cooperated despite being exploited
                self._set_reputation(donor_id, self._get_reputation(donor_id) + delta)
            else:
                # Defection decreases reputation, more if the other cooperated
                delta = -0.5
                if recipient_action == 'cooperate':
                    delta = -1.0  # They exploited a cooperator
                self._set_reputation(donor_id, self._get_reputation(donor_id) + delta)
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                # Recipient's action doesn't affect reputation as much, but still
                self._set_reputation(recipient_id, self._get_reputation(recipient_id) + 0.1)
            else:
                self._set_reputation(recipient_id, self._get_reputation(recipient_id) - 0.2)
        # Update counts
        self.coop_counts[donor_id] = self.coop_counts.get(donor_id, 0) + (1 if donor_action == 'cooperate' else 0)
        self.defect_counts[donor_id] = self.defect_counts.get(donor_id, 0) + (1 if donor_action == 'defect' else 0)

    def decide(self) -> bool:
        # Get opponent ID from context
        opp_id = self._ctx_opponent_id
        # If we have history with this opponent, use that
        if opp_id in self.history:
            hist = self.history[opp_id]
            # If we have at least one interaction, mimic if they mostly cooperate
            if len(hist) > 0:
                coop_against_me = sum(1 for _, their in hist if their == 'cooperate')
                # If they cooperated in most interactions, cooperate; else defect
                if coop_against_me >= len(hist) * 0.6:
                    return True
                else:
                    return False
        # Otherwise use reputation
        rep = self._get_reputation(opp_id)
        # Adjust threshold based on overall environment (learn over time)
        # If total observed is large, threshold can adapt
        if self.total_observed > 100:
            # If average reputation is low, be more cautious
            avg_rep = sum(self.reputation.values()) / max(1, len(self.reputation))
            self.threshold = min(0.5, max(-0.5, avg_rep * 0.1))
        # Cooperate if reputation is above threshold
        return rep >= self.threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both parties
        self._update_reputation(donor_id, donor_action, recipient_id, recipient_action)
        # If I am involved in this interaction, record history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            if donor_id == self.agent_id:
                my_action = donor_action
                their_action = recipient_action
                opp_id = recipient_id
            else:
                my_action = recipient_action
                their_action = donor_action
                opp_id = donor_id
            # Store history
            if opp_id not in self.history:
                self.history[opp_id] = []
            self.history[opp_id].append((my_action, their_action))
            # Keep history limited to last 10 interactions per opponent
            if len(self.history[opp_id]) > 10:
                self.history[opp_id].pop(0)
            # Update my last action
            self.last_my_action = my_action
        # Increment round count when I observe a self-judgment (one per round)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1

