class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.own_coop_count = 0
        self.own_defect_count = 0
        self.round = 0
        self.last_opponent = None
        self.opponent_histories = {}
        self.generation = 0
        self.opponent_coop_rate = {}
        self.opponent_observed_actions = {}
        self.self_actions = []
        self.my_recent_coop = []

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.last_opponent = opponent

        # Initialize opponent data if new
        if opponent not in self.opponent_coop_rate:
            self.opponent_coop_rate[opponent] = 0.5
            self.opponent_observed_actions[opponent] = []

        # Get reputation of opponent
        rep = self.reputation.get(opponent, 0.0)

        # If no direct history, use reputation
        if len(self.opponent_observed_actions.get(opponent, [])) == 0:
            if rep > 0.6:
                return True
            elif rep < 0.4:
                return False
            else:
                # Use own recent behavior as heuristic
                if len(self.my_recent_coop) > 0:
                    return self.my_recent_coop[-1]
                return True

        coop_rate = self.opponent_coop_rate[opponent]
        # If opponent cooperates often and reputation decent, cooperate
        if coop_rate > 0.7 and rep > 0.3:
            return True
        # If opponent defects often, defect
        if coop_rate < 0.4:
            return False
        # Tit-for-tat with forgiveness: cooperate if last action was cooperate
        last_actions = self.opponent_observed_actions[opponent]
        if last_actions:
            last = last_actions[-1]
            if last == 'cooperate':
                return True
            else:
                # Forgive with 20% chance to avoid endless defection
                return random.random() < 0.2
        return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update round counter on self observation
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round += 1
            if self.round % 30 == 0:
                self.generation += 1
                # Reset some state each generation
                self.opponent_observed_actions = {}
                self.opponent_coop_rate = {}
                self.my_recent_coop = []

        # Update own action if self
        if donor_id == self.agent_id:
            self.own_coop_count += 1 if donor_action == 'cooperate' else 0
            self.own_defect_count += 1 if donor_action == 'defect' else 0
            self.self_actions.append(donor_action)
            self.my_recent_coop.append(donor_action == 'cooperate')
            if len(self.my_recent_coop) > 30:
                self.my_recent_coop.pop(0)

        # Update reputation of donor based on action toward recipient
        # Simple: cooperate gives +1, defect gives -1 (capped)
        if donor_id != self.agent_id:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0)
            if donor_action == 'cooperate':
                self.reputation[donor_id] += 0.1
            else:
                self.reputation[donor_id] -= 0.1
            # Clamp to [-1, 1]
            self.reputation[donor_id] = max(-1.0, min(1.0, self.reputation[donor_id]))

        # Update opponent-specific data if we are observing a pair involving our opponent
        if donor_id == self.last_opponent:
            self._record_opponent_action(donor_id, donor_action)
        if recipient_id == self.last_opponent:
            self._record_opponent_action(recipient_id, recipient_action)

        # Also record any observations of known opponents
        for opp in list(self.opponent_observed_actions.keys()):
            if donor_id == opp:
                self._record_opponent_action(opp, donor_action)
            if recipient_id == opp:
                self._record_opponent_action(opp, recipient_action)

    def _record_opponent_action(self, opp_id, action):
        if opp_id not in self.opponent_observed_actions:
            self.opponent_observed_actions[opp_id] = []
        self.opponent_observed_actions[opp_id].append(action)
        # Keep last 30 actions
        if len(self.opponent_observed_actions[opp_id]) > 30:
            self.opponent_observed_actions[opp_id].pop(0)
        # Update coop rate
        coop = sum(1 for a in self.opponent_observed_actions[opp_id] if a == 'cooperate')
        self.opponent_coop_rate[opp_id] = coop / len(self.opponent_observed_actions[opp_id])

